from openpyxl import load_workbook
p='inputs/CHIP_DP10_GQ20_PASS/230209_Exome_GRCh38_CHIP_179-P1.xlsx'
for ro in [True,False]:
 w=load_workbook(p,read_only=ro,data_only=True); s=w.active
 if ro: s.reset_dimensions()
 print('ro',ro,'max',s.max_row,s.max_column)
 for i,row in zip(range(4),s.iter_rows(values_only=True)):
  print(i,row)
PY"

