/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['openpyxl','xlsx2csv']:
 url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=8&onlyActiveTags=true'
 try:
  with urllib.request.urlopen(url,timeout=30) as r:d=json.load(r)
  print(repo, [x['name'] for x in d.get('tags',[])[:8]])
 except Exception as e: print(repo, type(e).__name__)
PY"

